static uchar const k1024_e[ 3 ] = { 0x01,0x00,0x01 };

static void
test_key( char const *  name,
          uchar const * n,       ulong n_sz,
          uchar const * e,       ulong e_sz,
          uchar const * pkcs1_sha256, uchar const * pss_sha256,
          uchar const * pkcs1_sha384, uchar const * pss_sha384,
          uchar const * pkcs1_sha512, uchar const * pss_sha512 ) {
  FD_LOG_NOTICE(( "testing %s", name ));

  fd_rsa_pubkey_t key[1];
  FD_TEST( fd_rsa_pubkey_init( key, n, n_sz, e, e_sz )==key );
  FD_TEST( key->n_sz==n_sz );

  /* Leading zero bytes in the encoding are tolerated */
  uchar n_pad[ FD_RSA_MOD_SZ_MAX+2UL ] = {0};
  memcpy( n_pad+2UL, n, n_sz );
  uchar e_pad[ 4 ] = { 0, 0, 0, 0 };
  FD_TEST( e_sz<=3UL );
  memcpy( e_pad+4UL-e_sz, e, e_sz );
  fd_rsa_pubkey_t key2[1];
  FD_TEST( fd_rsa_pubkey_init( key2, n_pad, n_sz+2UL, e_pad, 4UL )==key2 );
  FD_TEST( 0==memcmp( key, key2, sizeof(fd_rsa_pubkey_t) ) );

  struct { uchar const * pkcs1; uchar const * pss; int hash; } const vec[3] = {
    { pkcs1_sha256, pss_sha256, FD_RSA_HASH_SHA256 },
    { pkcs1_sha384, pss_sha384, FD_RSA_HASH_SHA384 },
    { pkcs1_sha512, pss_sha512, FD_RSA_HASH_SHA512 },
  };

  for( ulong i=0UL; i<3UL; i++ ) {
    int hash = vec[i].hash;
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pkcs1, n_sz, msg, MSG_SZ, hash )==FD_RSA_SUCCESS );
    FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pss,   n_sz, msg, MSG_SZ, hash )==FD_RSA_SUCCESS );

    /* Scheme confusion */
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pss,   n_sz, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pkcs1, n_sz, msg, MSG_SZ, hash )==FD_RSA_FAILURE );

    /* Hash confusion */
    for( ulong j=0UL; j<3UL; j++ ) {
      if( j==i ) continue;
      FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pkcs1, n_sz, msg, MSG_SZ, vec[j].hash )==FD_RSA_FAILURE );
      FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pss,   n_sz, msg, MSG_SZ, vec[j].hash )==FD_RSA_FAILURE );
    }
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pkcs1, n_sz, msg, MSG_SZ, 3 )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pss,   n_sz, msg, MSG_SZ, 3 )==FD_RSA_FAILURE );

    /* Wrong message */
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pkcs1, n_sz, msg, MSG_SZ-1UL, hash )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pss,   n_sz, msg, MSG_SZ-1UL, hash )==FD_RSA_FAILURE );

    /* Wrong signature length */
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, vec[i].pkcs1, n_sz-1UL, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, vec[i].pss,   n_sz-1UL, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, n_pad, n_sz+1UL, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, n_pad, n_sz+1UL, msg, MSG_SZ, hash )==FD_RSA_FAILURE );

    /* Bit flips anywhere in the signature */
    uchar bad[ FD_RSA_MOD_SZ_MAX ];
    for( ulong off=0UL; off<n_sz; off+=fd_ulong_max( 1UL, n_sz/23UL ) ) {
      memcpy( bad, vec[i].pkcs1, n_sz ); bad[ off ] ^= (uchar)( 1U<<(off&7UL) );
      FD_TEST( fd_rsa_verify_pkcs1_v15( key, bad, n_sz, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
      memcpy( bad, vec[i].pss, n_sz ); bad[ off ] ^= (uchar)( 1U<<(off&7UL) );
      FD_TEST( fd_rsa_verify_pss( key, bad, n_sz, msg, MSG_SZ, hash )==FD_RSA_FAILURE );
    }
  }

  /* Signature representative out of range: s = n and s = n+1 */
  uchar big[ FD_RSA_MOD_SZ_MAX ];
  memcpy( big, n, n_sz );
  FD_TEST( fd_rsa_verify_pkcs1_v15( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  FD_TEST( fd_rsa_verify_pss      ( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  big[ n_sz-1UL ]++;
  FD_TEST( fd_rsa_verify_pkcs1_v15( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  memset( big, 0xff, n_sz );
  FD_TEST( fd_rsa_verify_pss( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  memset( big, 0x00, n_sz );
  FD_TEST( fd_rsa_verify_pkcs1_v15( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  FD_TEST( fd_rsa_verify_pss      ( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  big[ n_sz-1UL ] = 1;  /* s=1 => em=1 */
  FD_TEST( fd_rsa_verify_pkcs1_v15( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  FD_TEST( fd_rsa_verify_pss      ( key, big, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );

  /* Signature under a different key */
  if( n_sz==sizeof(k2048_n) && n!=k2048_n ) {
    FD_TEST( fd_rsa_verify_pkcs1_v15( key, k2048_pkcs1_sha256, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
    FD_TEST( fd_rsa_verify_pss      ( key, k2048_pss_sha256,   n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_FAILURE );
  }
}

static void
test_pubkey_init_rejects( void ) {
  fd_rsa_pubkey_t key[1];
  uchar n[ FD_RSA_MOD_SZ_MAX+1UL ];
  uchar e[ 9 ];

  /* 1024 bit keys are too small */
  FD_TEST( !fd_rsa_pubkey_init( key, k1024_n, sizeof(k1024_n), k1024_e, sizeof(k1024_e) ) );

  /* 4104 bit keys are too large, but 4096 with leading zero is fine */
  memset( n, 0xff, sizeof(n) );
  FD_TEST( !fd_rsa_pubkey_init( key, n, sizeof(n), k2048_e, sizeof(k2048_e) ) );
  n[0] = 0x00;
  FD_TEST(  fd_rsa_pubkey_init( key, n, sizeof(n), k2048_e, sizeof(k2048_e) ) );
  FD_TEST( key->mod_bits==4096UL && key->n_sz==512UL && key->limb_cnt==64UL );
  n[1] = 0x7f;
  FD_TEST( key==fd_rsa_pubkey_init( key, n, sizeof(n), k2048_e, sizeof(k2048_e) ) );
  FD_TEST( key->mod_bits==4095UL && key->n_sz==512UL );

  /* Even modulus */
  memcpy( n, k2048_n, sizeof(k2048_n) );
  n[ sizeof(k2048_n)-1UL ] &= (uchar)~1U;
  FD_TEST( !fd_rsa_pubkey_init( key, n, sizeof(k2048_n), k2048_e, sizeof(k2048_e) ) );

  /* Zero / empty */
  memset( n, 0, sizeof(n) );
  FD_TEST( !fd_rsa_pubkey_init( key, n, sizeof(n), k2048_e, sizeof(k2048_e) ) );
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, 0UL, k2048_e, sizeof(k2048_e) ) );
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 0UL ) );

  /* Exponent: even, too small, too large */
  e[0] = 0x02;
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 1UL ) );
  e[0] = 0x01;
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 1UL ) );
  e[0] = 0x00;
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 1UL ) );
  e[0] = 0x03;
  FD_TEST(  fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 1UL ) );
  FD_TEST( key->e==3UL );
  memset( e, 0xff, sizeof(e) );
  FD_TEST( !fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 9UL ) );
  FD_TEST(  fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 8UL ) );
  FD_TEST( key->e==ULONG_MAX );
  e[0] = 0x00;
  FD_TEST(  fd_rsa_pubkey_init( key, k2048_n, sizeof(k2048_n), e, 9UL ) );
  FD_TEST( key->e==ULONG_MAX );

  FD_TEST( !fd_rsa_pubkey_init( NULL, k2048_n, sizeof(k2048_n), k2048_e, sizeof(k2048_e) ) );
  FD_TEST( !fd_rsa_pubkey_init( key,  NULL,    sizeof(k2048_n), k2048_e, sizeof(k2048_e) ) );
  FD_TEST( !fd_rsa_pubkey_init( key,  k2048_n, sizeof(k2048_n), NULL,    sizeof(k2048_e) ) );
}

static void
bench( char const *  name,
       uchar const * n,   ulong n_sz,
       uchar const * e,   ulong e_sz,
       uchar const * sig ) {
  fd_rsa_pubkey_t key[1];
  FD_TEST( fd_rsa_pubkey_init( key, n, n_sz, e, e_sz ) );
  ulong iter = 200UL;
  long dt = -fd_log_wallclock();
  for( ulong i=0UL; i<iter; i++ )
    FD_TEST( fd_rsa_verify_pss( key, sig, n_sz, msg, MSG_SZ, FD_RSA_HASH_SHA256 )==FD_RSA_SUCCESS );
  dt += fd_log_wallclock();
  FD_LOG_NOTICE(( "%s verify: %.1f us", name, (double)dt/(double)iter/1e3 ));
}

int
main( int     argc,
      char ** argv ) {
  fd_boot( &argc, &argv );

# define KEY( k ) k##_n, sizeof(k##_n), k##_e, sizeof(k##_e), \
                  k##_pkcs1_sha256, k##_pss_sha256,             \
                  k##_pkcs1_sha384, k##_pss_sha384,             \
                  k##_pkcs1_sha512, k##_pss_sha512
  test_key( "rsa2048 e=65537", KEY( k2048   ) );
  test_key( "rsa3072 e=65537", KEY( k3072   ) );
  test_key( "rsa4096 e=65537", KEY( k4096   ) );
  test_key( "rsa2048 e=3",     KEY( k2048e3 ) );
  test_key( "rsa2049 e=65537", KEY( k2049   ) );
# undef KEY

  test_pubkey_init_rejects();

  bench( "rsa2048", k2048_n, sizeof(k2048_n), k2048_e, sizeof(k2048_e), k2048_pss_sha256 );
  bench( "rsa3072", k3072_n, sizeof(k3072_n), k3072_e, sizeof(k3072_e), k3072_pss_sha256 );
  bench( "rsa4096", k4096_n, sizeof(k4096_n), k4096_e, sizeof(k4096_e), k4096_pss_sha256 );

  FD_LOG_NOTICE(( "pass" ));
  fd_halt();
  return 0;
}
